interface ToastManager {
  add: (message: Exclude<React.ReactNode, null | undefined | boolean>, options?: ToastOptions) => string;
  remove: (key: string) => void;
}

interface ToastOptions {
  title?: React.ReactNode;
  variant?: 'neutral' | 'success' | 'warning' | 'danger';
  duration?: number;
  onDismiss?: () => void;
  className?: string;
}

interface ToastOwnProps {
  message: Exclude<React.ReactNode, null | undefined | boolean>;
  title?: React.ReactNode;
  variant?: 'neutral' | 'success' | 'warning' | 'danger';
  duration?: number;
  onDismiss?: () => void;
}

interface ToastProps extends ToastOwnProps {
  className?: string;
}

interface ToastProviderProps {
  children?: React.ReactNode;
  maxVisible?: number;
  placement?: 'top-start' | 'top-end' | 'bottom-start' | 'bottom-end';
  className?: string;
}
